def is_palindrome(s):
    return s == s[::-1]

def count_insertions_to_palindrome(s):
    n = len(s)
    count = 0
    for i in range(n + 1):
        new_s = s[:i] + 'a' + s[i:]
        if is_palindrome(new_s):
            count += 1
    return count

import sys
input = sys.stdin.read
data = input().split()

T = int(data[0])
strings = data[1:]

results = []
for s in strings:
    results.append(count_insertions_to_palindrome(s))

for result in results:
    print(result)
